import { connection } from 'next/server'

export default async function CurrentTimestamp() {
  // Stops prerendering: everything below runs only once a real request arrives,
  // so the timestamp is fresh on every page load instead of frozen at build time.
  await connection()
  const now = new Date()

  return <time dateTime={now.toISOString()}>{now.toISOString()}</time>
}

